CREATE TABLE truss.runtime_catalog_key_backfill (transition_id bigint PRIMARY KEY DEFAULT nextval('truss.runtime_object_transition_seq'), registration_id uuid NOT NULL REFERENCES truss.catalog_registration_request (registration_id) DEFERRABLE INITIALLY DEFERRED, writer_xid xid8 NOT NULL, actor_oid oid NOT NULL, revision int NOT NULL REFERENCES truss.schema_rev (rev), object_id bigint NOT NULL, type_id int NOT NULL, object_image jsonb NOT NULL, after_keys jsonb NOT NULL, effects jsonb NOT NULL, UNIQUE (registration_id, object_id, type_id), CHECK (jsonb_typeof(object_image) = 'object' AND jsonb_typeof(after_keys) = 'array' AND jsonb_typeof(effects) = 'array' AND jsonb_array_length(effects) > 0)); CREATE INDEX runtime_catalog_key_backfill_owner ON truss.runtime_catalog_key_backfill USING btree (object_id, type_id, transition_id DESC); CREATE INDEX runtime_catalog_key_backfill_writer ON truss.runtime_catalog_key_backfill USING btree (writer_xid); CREATE TRIGGER runtime_catalog_key_backfill_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.runtime_catalog_key_backfill EXECUTE FUNCTION truss.catalog_immutable(); REVOKE ALL ON truss.runtime_catalog_key_backfill FROM public; CREATE CONSTRAINT TRIGGER runtime_catalog_key_backfill_commit AFTER INSERT ON truss.runtime_catalog_key_backfill DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION truss.runtime_object_commit_check(); ALTER TABLE truss.runtime_catalog_key_backfill ENABLE ALWAYS TRIGGER runtime_catalog_key_backfill_commit; ALTER TABLE truss.runtime_catalog_key_backfill ENABLE ALWAYS TRIGGER runtime_catalog_key_backfill_immutable